import { Textarea } from '@absoluteui/components/textarea';

const host = document.createElement('div');
document.body.append(host);
const comments = Textarea.create(host, { label: 'Comments', name: 'comments', required: true, maxLength: 500, showCounter: true });
host.addEventListener('aui-change', () => {
  host.dataset.valid = String(comments.validity.valid);
});

import { Textarea } from '@absoluteui/components/textarea';

